 void drawRotarySlider(Graphics&g,int x,int y,int w,int h,float pos,float start,float end,Slider&)override{float r=jmin(w,h)*.5f-7,cx=x+w*.5f,cy=y+h*.5f;Path track;track.addCentredArc(cx,cy,r,r,0,start,end,true);g.setColour(line);g.strokePath(track,PathStrokeType(3));Path arc;arc.addCentredArc(cx,cy,r,r,0,start,start+pos*(end-start),true);g.setColour(accent);g.strokePath(arc,PathStrokeType(3));g.setColour(Colour(0xff222e3d));g.fillEllipse(cx-r+6,cy-r+6,2*r-12,2*r-12);float a=start+pos*(end-start);g.setColour(ink);g.drawLine(cx+std::sin(a)*(r-15),cy-std::cos(a)*(r-15),cx+std::sin(a)*(r-7),cy-std::cos(a)*(r-7),2);}
 void drawLinearSlider(Graphics&g,int x,int y,int w,int h,float position,float minimum,float maximum,Slider::SliderStyle type,Slider&slider)override{
  if(type!=Slider::LinearVertical){LookAndFeel_V4::drawLinearSlider(g,x,y,w,h,position,minimum,maximum,type,slider);return;}
  float cx=x+w*.5f;g.setColour(bg);g.fillRoundedRectangle(cx-3,(float)y,6,(float)h,3);g.setFont(8);for(float db:{0.f,-6.f,-12.f,-24.f,-48.f}){float yy=y+h*(1-(float)slider.valueToProportionOfLength(Decibels::decibelsToGain(db)));g.setColour(muted.withAlpha(.5f));g.drawLine(cx-18,yy,cx-8,yy,1);g.drawText(String((int)db),x,roundToInt(yy)-6,jmax(8,w/2-22),12,Justification::centredRight);}
  Rectangle<float>cap(cx-16,position-11,32,22);ColourGradient metal(Colour(0xffc8d0d7),0,cap.getY(),Colour(0xff697785),0,cap.getBottom(),false);metal.addColour(.45,Colour(0xffa4afb9));metal.addColour(.5,Colour(0xffd9e0e5));g.setGradientFill(metal);g.fillRoundedRectangle(cap,2);g.setColour(bg.withAlpha(.7f));g.drawRoundedRectangle(cap,2,1);g.drawLine(cap.getX()+3,position,cap.getRight()-3,position,1.2f);
 }
 void drawButtonBackground(Graphics&g,Button&b,const Colour&,bool over,bool)override{g.setColour(b.getToggleState()?Colour(0xff263f42):over?Colour(0xff283544):panelColour);g.fillRoundedRectangle(b.getLocalBounds().toFloat(),5);g.setColour(line);g.drawRoundedRectangle(b.getLocalBounds().toFloat().reduced(.5f),5,1);if(b.getToggleState()){g.setColour(accent);g.fillRect(8,b.getHeight()-2,b.getWidth()-16,2);}}
