struct MidiConfig:Component{
 SynthMavenProcessor&p;ComboBox target,cc,channel;TextButton assign{"ASSIGN"},learn{"LEARN"},cancel{"CANCEL LEARN"},remove{"REMOVE"},clear{"CLEAR ALL MAPS"},bluetooth{"BLUETOOTH MIDI"};Label instructions,status,mapping;
 std::vector<String>ids;
 MidiConfig(SynthMavenProcessor&proc):p(proc){for(Component*c:std::initializer_list<Component*>{&target,&cc,&channel,&assign,&learn,&cancel,&remove,&clear,&bluetooth,&instructions,&status,&mapping})addAndMakeVisible(c);
  bluetooth.setEnabled(BluetoothMidiDevicePairingDialogue::isAvailable());bluetooth.onClick=[] {if(!BluetoothMidiDevicePairingDialogue::open())AlertWindow::showMessageBoxAsync(MessageBoxIconType::WarningIcon,"Bluetooth MIDI","Bluetooth MIDI pairing is unavailable. In a DAW/AUv3, route paired MIDI through the host.");};
  int l=p.selectedLayer.load();for(int i=0;i<sm_parameter_count();i++)if(p.visibleParameter(i)){ids.push_back(p.parameterId(i));target.addItem("L"+String(l+1)+" / "+p.parameterLabel(i)+" / "+String(i),(int)ids.size());}for(auto key:{"enabled","gain","pan","transpose","channel","portamento","mute","solo","split","splitPoint","splitSide","sampleOn"}){ids.push_back(p.layerId(l,key));target.addItem("L"+String(l+1)+" / "+key,(int)ids.size());}for(auto key:OscillatorRack::keys){ids.push_back(p.layerId(l,key));target.addItem("L"+String(l+1)+" / "+key,(int)ids.size());}for(auto key:p.sampleKeys){ids.push_back(p.sampleId(l,key));target.addItem("L"+String(l+1)+" / SAMPLER / "+key,(int)ids.size());}for(auto key:{"masterGain","masterPan","masterMute"}){ids.push_back(key);target.addItem(key,(int)ids.size());}for(int t:{l,8}){for(auto key:{"root","reference","bypass","scala"}){ids.push_back(p.tuningId(t,key));target.addItem((t==8?String("MASTER"):"L"+String(l+1))+" TUNING / "+key,(int)ids.size());}for(int n=0;n<12;n++){ids.push_back(p.tuningId(t,"note"+String(n)));target.addItem((t==8?String("MASTER"):"L"+String(l+1))+" TUNING / note "+String(n),(int)ids.size());}}ids.push_back("masterTuning");target.addItem("MASTER TUNING ON/OFF",(int)ids.size());target.setSelectedId(1);target.onChange=[this]{refresh();};for(int i=1;i<=119;i++)if(i!=32)cc.addItem("CC "+String(i),i);cc.setSelectedId(74);channel.addItem("ALL CHANNELS",1);for(int i=1;i<=16;i++)channel.addItem("CH "+String(i),i+1);channel.setSelectedId(1);
  instructions.setText("Select a layer above, choose a target, then Learn and move a controller.\nYou can also right-click any synthesis knob for MIDI Learn.\nDefault CCs: 7 level, 10 pan, 16-19 macros, 71 resonance, 74 cutoff, 5 glide time, 65 portamento on/off.\nNotes, sustain, pitch bend, mod wheel and aftertouch pass to each enabled layer's MIDI channel.",dontSendNotification);instructions.setColour(Label::textColourId,muted);instructions.setFont(13);
  assign.onClick=[this]{p.assignMapping(channel.getSelectedId()-1,cc.getSelectedId(),chosen());refresh();};learn.onClick=[this]{p.beginLearn(chosen());refresh();};cancel.onClick=[this]{p.cancelLearn();refresh();};remove.onClick=[this]{p.removeMapping(chosen());refresh();};clear.onClick=[this]{p.clearMappings();refresh();};refresh();}
 String chosen()const{int i=target.getSelectedItemIndex();return isPositiveAndBelow(i,(int)ids.size())?ids[(size_t)i]:String();}
 void refresh(){status.setText(p.controllerStatus()+"\n"+p.learningDescription(),dontSendNotification);mapping.setText("Mapping: "+p.mappingDescription(chosen()),dontSendNotification);}
 void resized()override{int w=getWidth();instructions.setBounds(8,4,w-16,100);target.setBounds(8,116,w-16,32);channel.setBounds(8,160,150,32);cc.setBounds(170,160,120,32);assign.setBounds(302,160,100,32);learn.setBounds(414,160,90,32);remove.setBounds(516,160,90,32);mapping.setBounds(8,206,w-16,30);status.setBounds(8,244,w-16,70);cancel.setBounds(8,330,150,32);clear.setBounds(170,330,160,32);bluetooth.setBounds(342,330,180,32);}
};
