void SynthMavenEditor::filter(){syncingBrowser=true;filtered.clear();String q=search.getText().trim();int e=engineFilter.getSelectedId()-2;const auto&f=processor.factory();for(size_t i=0;i<f.size();i++)if((e<0||f[i].catalogIndex==e)&&(typeFilter.getSelectedId()<=1||typeFilter.getText()==f[i].soundType)&&(collectionFilter.getSelectedId()<=1||collectionFilter.getText()==f[i].collection)&&(characterFilter.getSelectedId()<=1||StringArray::fromTokens(f[i].character," ","").contains(characterFilter.getText()))&&(q.isEmpty()||f[i].name.containsIgnoreCase(q)||f[i].engine.containsIgnoreCase(q)||f[i].soundType.containsIgnoreCase(q)||f[i].collection.containsIgnoreCase(q)||f[i].character.containsIgnoreCase(q)))filtered.push_back((int)i);browser.updateContent();int row=-1;for(size_t i=0;i<filtered.size();i++)if(!processor.sampleEnabled(processor.selectedLayer.load())&&filtered[i]==processor.getCurrentProgram())row=(int)i;browser.selectRow(row,false,true);syncingBrowser=false;repaint();}
int SynthMavenEditor::getNumRows(){return (int)filtered.size();}
void SynthMavenEditor::paintListBoxItem(int row,Graphics&g,int w,int h,bool selected){if(!isPositiveAndBelow(row,(int)filtered.size()))return;auto&f=processor.factory()[(size_t)filtered[(size_t)row]];g.fillAll(selected?Colour(0xff203d3e):bg);if(selected){g.setColour(accent);g.fillRect(0,0,3,h);}g.setFont(Font(13,Font::bold));g.setColour(selected?accent:ink);g.drawText(f.name,14,5,w-20,20,Justification::centredLeft);g.setFont(10);g.setColour(muted);g.drawText(f.engine+" / "+String(filtered[(size_t)row]+1),14,26,w-20,15,Justification::centredLeft);}
void SynthMavenEditor::selectedRowsChanged(int row){if(!syncingBrowser&&isPositiveAndBelow(row,(int)filtered.size())){processor.setCurrentProgram(filtered[(size_t)row]);if(getWidth()<1040&&libraryOpen){libraryOpen=false;resized();}}}
void SynthMavenEditor::selectRelative(int d){int n=processor.getNumPrograms();processor.setCurrentProgram((processor.getCurrentProgram()+d+n)%n);}
void SynthMavenEditor::rebuild(){panel->configure(tab);panel->setSize(jmax(viewport.getMaximumVisibleWidth()-2,getWidth()<1040?(tab==3||tab==7||((tab==0||tab==6)&&processor.sampleEnabled(processor.selectedLayer.load()))?900:780):0),panel->getHeight());viewport.setViewPosition(0,0);repaint();}
void SynthMavenEditor::timerCallback(){panel->refresh();int selected=processor.selectedLayer.load();unsigned revision=processor.uiRevision.load();int sampled=processor.sampleEnabled(selected)?1:0;if(sampled!=lastSample){lastSample=sampled;filter();rebuild();}int master=processor.parameters.getRawParameterValue("masterTuning")->load()>=.5f;if(master!=lastMaster){lastMaster=master;rebuild();}if(lastLayer!=selected){lastLayer=selected;search.setText("",false);engineFilter.setSelectedId(1,dontSendNotification);}if(lastProgram!=processor.getCurrentProgram()||lastRevision!=revision){lastProgram=processor.getCurrentProgram();lastRevision=revision;filter();rebuild();}for(int l=0;l<8;l++){auto&b=layerButtons[(size_t)l];bool on=processor.parameters.getRawParameterValue(processor.layerId(l,"enabled"))->load()>=.5f;b.setButtonText(getWidth()<1040?"L"+String(l+1):"L"+String(l+1)+" / "+processor.layerInstrument(l)+(on?" ON":" OFF"));b.setTooltip(processor.layerInstrument(l)+" / "+processor.displayName(l));b.setToggleState(l==selected,dontSendNotification);}repaint(scopeBounds);repaint(headerBounds);}
